'use strict';
/* Read-only MIR TEST preflight for the exact unique run generated by
 * native-qa-fixture.cjs. No historic fixed shift IDs, no punch RPC mutations. */
const fs=require('node:fs'),path=require('node:path');
const HOST='hxtztkmbfpmzrieccwsg.supabase.co';
const ORG='8aabc1c9-bd01-4ca1-ad62-b89b575a6bf9',JOB='7da20261-1114-4000-8000-000000000001';
const LEAD_MEMBER='552233d5-ae18-4c14-be85-0206e6f18549';
const ACTORS=Object.freeze([
 Object.freeze({key:'EMPLOYEE',name:'employee',id:'3980647a-d83a-48ad-9d90-8fc2b314807f'}),
 Object.freeze({key:'CHEF',name:'chef',id:'ec421778-b39b-492e-9e4b-5e044015e98f'})
]);
const UUID=/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/;
const KEY=/^sb_publishable_[A-Za-z0-9_-]+$/;
function loadManifest(file=path.resolve('artifacts/phase11/native-qa-run-manifest.json')){
 if(!fs.existsSync(file))throw Error('MIR TEST unique QA manifest missing: lifecycle start required');
 return JSON.parse(fs.readFileSync(file,'utf8'));
}
function validateManifest(m,now=new Date()){
 if(!m||m.ok!==true||m.state!=='active'||m.projectRef!==HOST.split('.')[0]
  ||!UUID.test(m.runId||'')||m.marker!=='QA-NATIVE-RUN-'+m.runId.replaceAll('-','')
  ||m.jobId!==JOB||m.workDate!==now.toISOString().slice(0,10))
  throw Error('Per-run QA manifest invalid, old or from wrong environment/date');
 const ids=[m.employee?.shift,m.employee?.segment,m.chef?.shift,m.chef?.segment,m.lead?.assignmentId,m.lead?.taskId];
 if(ids.some(v=>!UUID.test(v||''))||new Set(ids).size!==6
   ||m.employee.id!==ACTORS[0].id||m.chef.id!==ACTORS[1].id||m.lead.memberId!==LEAD_MEMBER)
   throw Error('Per-run QA identities incorrect or duplicated');
 return m;
}
function configuration(env,manifest){
 validateManifest(manifest);
 if(env.MIR_SANDBOX_ORG_ID!==ORG)throw Error('Organisation TEST incorrecte; accès refusé');
 const key=env.MIR_SANDBOX_PUBLISHABLE_KEY;
 if(!KEY.test(key||''))throw Error('Clé publique MIR TEST manquante ou invalide');
 return {key,manifest,actors:ACTORS.map(a=>{
   const email=env['MIR_SANDBOX_'+a.key+'_EMAIL'],password=env['MIR_SANDBOX_'+a.key+'_PASSWORD'];
   if(!email||!password)throw Error('Compte QA absent: '+a.key);
   return {...a,email,password,shift:manifest[a.name].shift,segment:manifest[a.name].segment,marker:manifest.marker};
 })};
}
function checkState(data,actor,nowMs=Date.now()){
 const shift=data?.activeShift,segment=shift?.segment;
 if(!shift||shift.id!==actor.shift||shift.device_id!==actor.marker||
   shift.status!=='active'||shift.ended_at!==null||shift.ended_at===undefined||
   segment?.id!==actor.segment||segment?.job_id!==JOB||
   segment?.segment_type!=='job'||segment?.ended_at!==null||segment?.ended_at===undefined)
   throw Error('Quart/segment QA actif manquant ou incohérent: '+actor.key);
 const started=Date.parse(shift.started_at),seconds=(nowMs-started)/1000;
 if(!Number.isFinite(seconds)||seconds<900||seconds>8*3600)
   throw Error('Heure du quart QA hors de la fenêtre 15 min–8 h: '+actor.key);
 return {role:actor.key,shiftId:actor.shift,segmentId:actor.segment,jobId:JOB,secondsActive:Math.floor(seconds)};
}
function checkLead(data,manifest){
 if(data?.role!=='chef_equipe'||data?.today!==manifest.workDate||
    data?.assignment?.id!==manifest.lead.assignmentId||data.assignment.jobId!==JOB||
    !Array.isArray(data.team)||!data.team.some(m=>m.id===LEAD_MEMBER)||
    !Array.isArray(data.tasks)||!data.tasks.some(t=>t.id===manifest.lead.taskId&&t.completedAt===null))
   throw Error('Affectation/équipe/tâche QA Chef du jour absente ou incohérente');
 return {assignmentId:manifest.lead.assignmentId,taskId:manifest.lead.taskId,jobId:JOB};
}
async function postJson(fetchFn,url,headers,data){
 const response=await fetchFn(url,{method:'POST',headers:{'content-type':'application/json',...headers},body:JSON.stringify(data),signal:AbortSignal.timeout(20000)});
 let body;try{body=await response.json();}catch{throw Error('Réponse QA illisible ('+response.status+')');}
 if(!response.ok)throw Error('Précondition QA RPC ou Auth refusée ('+response.status+')');
 return body;
}
async function run(env=process.env,fetchFn=fetch,manifest=loadManifest()){
 const c=configuration(env,manifest),base='https://'+HOST,results=[];
 for(const actor of c.actors){
   const session=await postJson(fetchFn,base+'/auth/v1/token?grant_type=password',
     {apikey:c.key},{email:actor.email,password:actor.password});
   if(session?.user?.id!==actor.id||!session.access_token)
     throw Error('Identité de compte QA inattendue: '+actor.key);
   const punch=await postJson(fetchFn,base+'/rest/v1/rpc/mir_punch_snapshot',
     {apikey:c.key,authorization:'Bearer '+session.access_token},{org:ORG,employee:null});
   const result=checkState(punch,actor);
   if(actor.key==='CHEF'){
     const lead=await postJson(fetchFn,base+'/rest/v1/rpc/mir_lead_today_snapshot',
       {apikey:c.key,authorization:'Bearer '+session.access_token},{org:ORG});
     result.lead=checkLead(lead,c.manifest);
   }
   results.push(result);
 }
 return {project:HOST,organization:ORG,fixture:'unique run '+c.manifest.runId,readOnly:true,roles:results};
}
if(require.main===module)run().then(r=>console.log('PASS MIR TEST native preflight: '+r.roles.length+' exact identities and fresh run-scoped shifts; no writes'))
 .catch(e=>{console.error('MIR TEST précondition: '+e.message);process.exitCode=1;});
module.exports={HOST,ORG,JOB,LEAD_MEMBER,ACTORS,loadManifest,validateManifest,configuration,checkState,checkLead,run};
